fn get_column(input: &Vec<Vec<i8>>, j: usize, m: usize, n: usize) -> Vec<i8> {
    // Extract the j-th column from the matrix
    // j must be < m, and we assume input has n rows
    let mut col = Vec::with_capacity(n);
    
    for i in 0..n {
        col.push(input[i][j]);
    }
    
    col
}

fn column_stack(input: Vec<Vec<i8>>, m: usize, n: usize) -> Vec<Vec<i8>> {
    // Create the transpose of the input matrix
    // Result will have m rows (one for each original column)
    // Each row will have n elements (one from each original row)
    let mut result = Vec::with_capacity(m);
    
    for j in 0..m {
        let mut new_row = Vec::with_capacity(n);
        for i in 0..n {
            new_row.push(input[i][j]);
        }
        result.push(new_row);
    }
    
    result
}